package app.kivo.store;
import android.content.pm.*;import android.os.Build;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Exact APK identity is learned automatically, independently of download/install history. */
final class ApkInspector {
 final MainActivity host;final File cache;final ExecutorService worker=Executors.newFixedThreadPool(2);volatile String active="";final Map<String,Object> locks=new ConcurrentHashMap<>();final Set<String> pending=ConcurrentHashMap.newKeySet();
 ApkInspector(MainActivity h){host=h;cache=new File(h.getCacheDir(),"apk-identity-v1");cache.mkdirs();}
 JSONObject asset(JSONObject app,long id)throws Exception{JSONArray list=app.optJSONArray("assets");if(list!=null)for(int i=0;i<list.length();i++){JSONObject a=list.getJSONObject(i);if(a.optLong("id")==id)return a;}throw new IOException("La publicación cambió; vuelve a comprobar la ficha.");}
 File file(JSONObject app,JSONObject a)throws Exception{return new File(cache,GithubClient.hash((app.optString("repo").toLowerCase(Locale.ROOT)+":"+a.getLong("id")+":"+a.optLong("size")+":"+a.optString("digest")).getBytes("UTF-8"))+".json");}
 JSONObject cached(JSONObject app,JSONObject a)throws Exception{File p=file(app,a);if(!p.isFile())return null;JSONObject m=new JSONObject(GithubClient.read(p));if(m.optInt("schema")!=1||!InstalledApps.validPackage(m.optString("package"))||!m.has("versionCode")||m.optLong("assetId")!=a.optLong("id"))return null;return m;}
 JSONObject identity(JSONObject app,long id)throws Exception{JSONObject a=asset(app,id);synchronized(locks.computeIfAbsent(file(app,a).getName(),k->new Object())){JSONObject m=cached(app,a);if(m!=null)return m;String repo=app.getString("repo"),url=a.getString("url");if(!RemoteApk.assetUrl(repo,url)||!a.optString("name").toLowerCase(Locale.ROOT).endsWith(".apk"))throw new IOException("Origen de APK no válido.");RemoteApk.Identity data=RemoteApk.inspect(new RemoteApk.HttpSource(url,a.getLong("size")));m=new JSONObject().put("schema",1).put("repo",repo).put("assetId",id).put("package",data.pkg).put("version",data.version).put("versionCode",data.code).put("minSdk",data.minSdk).put("checked",System.currentTimeMillis());GithubClient.write(file(app,a),m.toString());File[] all=cache.listFiles((dir,name)->name.endsWith(".json"));if(all!=null&&all.length>150){Arrays.sort(all,Comparator.comparingLong(File::lastModified));for(int i=0;i<all.length-120;i++)all[i].delete();}return m;}}
 void fields(JSONObject app,JSONObject m)throws Exception{app.put("package",m.getString("package")).put("versionCode",m.getLong("versionCode")).put("apkIdentityChecked",true).put("identityAssetId",m.getLong("assetId")).put("apkMinSdk",m.optInt("minSdk",1));if(!m.optString("version").isEmpty())app.put("version",m.getString("version"));}
 void restore(JSONObject app){try{long id=host.bestAsset(app.optJSONArray("assets"));if(id>0){JSONObject m=cached(app,asset(app,id));if(m!=null)fields(app,m);}}catch(Exception ignored){}}
 void state(String repo,String state,JSONObject m,String error){try{JSONObject out=m==null?new JSONObject():new JSONObject(m.toString());out.put("repo",repo).put("state",state).put("error",error==null?"":error);if(state.equals("ready")){boolean supported=out.optInt("minSdk",1)<=Build.VERSION.SDK_INT;out.put("downloadSupported",supported).put("nativeInstalled",false).put("updateAvailable",false);if(!supported)out.put("notice","Esta versión requiere Android API "+out.optInt("minSdk")+" o posterior.");try{int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo installed=host.getPackageManager().getPackageInfo(out.getString("package"),flags);out.put("nativeInstalled",true).put("installedCode",Long.toString(MainActivity.code(installed))).put("installedVersion",installed.versionName==null?"":installed.versionName);boolean newer=out.optLong("versionCode")>MainActivity.code(installed),same=true;if(repo.startsWith("fdroid/")||repo.startsWith("izzy/")){JSONObject source=repo.startsWith("izzy/")?host.izzy.entries.get(repo):host.fdroid.entries.get(repo);same=source!=null&&InstalledApps.sameSigner(source,host.signers(installed));if(newer&&!same)out.put("notice","Hay una versión más reciente, pero su firma no coincide con tu instalación.");}out.put("updateAvailable",newer&&same&&supported);}catch(PackageManager.NameNotFoundException absent){} }host.send("apkInspection",out);}catch(Exception e){try{host.send("apkInspection",new JSONObject().put("repo",repo).put("state","error").put("error","Android no pudo comprobar esta instalación."));}catch(Exception ignored){}}}

 void inspect(String raw){final String repo;try{repo=MainActivity.repo(raw);}catch(Exception e){return;}active=repo;if(repo.startsWith("fdroid/")||repo.startsWith("izzy/")){try{JSONObject a=repo.startsWith("izzy/")?host.izzy.find(repo):host.fdroid.find(repo);long id=host.bestAsset(a.optJSONArray("assets"));JSONObject m=new JSONObject().put("repo",repo).put("package",a.getString("package")).put("version",a.optString("version")).put("versionCode",a.optLong("versionCode")).put("assetId",id);state(repo,"ready",m,"");}catch(Exception e){state(repo,"error",null,e.getMessage());}return;}JSONObject app=host.catalog.get(repo);if(app==null||app.optBoolean("indexed"))return;long id=host.bestAsset(app.optJSONArray("assets"));if(id<1)return;String task=repo+":"+id;if(!pending.add(task))return;try{JSONObject marker=new JSONObject().put("assetId",id);state(repo,"checking",marker,"");worker.execute(()->{try{JSONObject current=host.catalog.get(repo);if(current==null)return;JSONObject m=identity(current,id);apply(repo,m);}catch(Exception e){try{state(repo,"error",new JSONObject().put("assetId",id),e.getMessage());}catch(Exception ignored){} }finally{pending.remove(task);}});}catch(Exception e){pending.remove(task);}}
 void apply(String repo,JSONObject m)throws Exception{JSONObject current=host.catalog.get(repo);if(current==null||host.bestAsset(current.optJSONArray("assets"))!=m.getLong("assetId"))return;if(!current.optBoolean("apkIdentityChecked")||current.optLong("identityAssetId")!=m.getLong("assetId")||!current.optString("package").equals(m.optString("package"))){JSONObject copy=new JSONObject(current.toString());fields(copy,m);host.catalog.put(repo,copy);host.publish();}host.installedApps.inspect(repo);host.installedApps.scan();state(repo,"ready",m,"");}
 /** Recheck against Android immediately before enqueue, including direct variant buttons. */
 boolean mayDownload(String repo,long id)throws Exception{JSONObject app=host.catalog.get(repo);if(app==null)throw new IOException("Vuelve a abrir la ficha.");JSONObject m=identity(app,id);if(m.optInt("minSdk",1)>Build.VERSION.SDK_INT)throw new IOException("El APK requiere una versión de Android más reciente.");try{PackageInfo installed=host.getPackageManager().getPackageInfo(m.getString("package"),0);if(MainActivity.code(installed)>=m.getLong("versionCode")){apply(repo,m);host.status("Ya tienes esta versión o una más reciente. Usa Abrir app.");return false;}}catch(PackageManager.NameNotFoundException ignored){}return true;}
 String packageFor(JSONObject app,long id)throws Exception{return identity(app,id).getString("package");}
 void recheckActive(){String repo=active;if(!repo.isEmpty())inspect(repo);}
 void close(){worker.shutdownNow();}
}
